Copy the workbook, read cached values from Sheet1, and choose column B for times before 09:45 and column C otherwise, leaving zero/missing values blank. Sum the resulting E2:E14 values into E15. Apply solid #FFC000 fill to E2:E15 and save.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill
from datetime import datetime, time

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def parse_time(v):
    if v is None:
        return None
    if isinstance(v, time):
        return v
    if isinstance(v, datetime):
        return v.time()
    if isinstance(v, (int, float)):
        try:
            frac = float(v) % 1.0
            secs = int(round(frac * 86400)) % 86400
            return time(secs // 3600, (secs // 60) % 60, secs % 60)
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            parts = s.split(":")
            h = int(parts[0])
            m = int(parts[1])
            sec = int(parts[2]) if len(parts) > 2 else 0
            return time(h, m, sec)
        except Exception:
            pass
        try:
            return datetime.fromisoformat(s).time()
        except Exception:
            return None
    return None

def to_number(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            return float(s)
        except Exception:
            return None
    return None

def clean_number(v):
    if v is None:
        return None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

threshold = time(9, 45, 0)

for r in range(2, 15):
    t = parse_time(vws.cell(row=r, column=1).value)
    val = None

    if t is not None:
        if t < threshold:
            src = vws.cell(row=r, column=2).value
        else:
            src = vws.cell(row=r, column=3).value

        val = clean_number(to_number(src))
        if val is not None and val == 0:
            val = None

    ws.cell(row=r, column=5).value = val

total = 0.0
for r in range(2, 15):
    v = ws.cell(row=r, column=5).value
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        total += v

total = clean_number(total)
if total is None or total == 0:
    ws.cell(row=15, column=5).value = None
else:
    ws.cell(row=15, column=5).value = total

fill = PatternFill(start_color="FFC000", end_color="FFC000", fill_type="solid")
for r in range(2, 16):
    ws.cell(row=r, column=5).fill = fill

wb.save(OUT)

print("E2:E15 =", [ws.cell(row=r, column=5).value for r in range(2, 16)])
```

